import * as React from 'react';
import { cleanup, render } from '@testing-library/react';
import { describe, it, expect, afterEach } from 'vitest';
import * as Menu from './index';

describe('repro: menu subtrigger composeRefs unstable identity', () => {
  afterEach(cleanup);
  it('does not infinitely re-render', () => {
    let renderCount = 0;
    function App() {
      const [count, setCount] = React.useState(0);
      renderCount++;
      const ref = React.useCallback((node: HTMLButtonElement | null) => {
        if (node) setCount((c) => c + 1);
      }, []);
      return (
        <Menu.Root>
          <Menu.Anchor>
            <button>open</button>
          </Menu.Anchor>
          <Menu.Portal>
            <Menu.Content>
              <Menu.Sub>
                <Menu.SubTrigger ref={ref}>sub</Menu.SubTrigger>
                <Menu.SubContent>
                  <Menu.Item>item</Menu.Item>
                </Menu.SubContent>
              </Menu.Sub>
            </Menu.Content>
          </Menu.Portal>
        </Menu.Root>
      );
    }
    render(<App />);
    expect(renderCount).toBeLessThan(100);
  });
});

