import * as React from 'react';
import { cleanup, render } from '@testing-library/react';
import { describe, it, expect, afterEach } from 'vitest';
import * as DropdownMenu from './index';

describe('repro: dropdown trigger composeRefs unstable identity', () => {
  afterEach(cleanup);
  it('does not infinitely re-render', () => {
    let renderCount = 0;
    function App() {
      const [count, setCount] = React.useState(0);
      renderCount++;
      const ref = React.useCallback((node: HTMLButtonElement | null) => {
        if (node) setCount((c) => c + 1);
      }, []);
      return (
        <DropdownMenu.Root>
          <DropdownMenu.Trigger ref={ref}>open</DropdownMenu.Trigger>
          <DropdownMenu.Portal>
            <DropdownMenu.Content>
              <DropdownMenu.Item>item</DropdownMenu.Item>
            </DropdownMenu.Content>
          </DropdownMenu.Portal>
        </DropdownMenu.Root>
      );
    }
    render(<App />);
    expect(renderCount).toBeLessThan(100);
  });
});

